<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Catalog;
use App\Domain\Catalog\Entity\SyllabusDocumentExtraction;use App\Domain\Catalog\Repository\SyllabusDocumentExtractionRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SyllabusDocumentExtractionRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineSyllabusDocumentExtractionRepository implements SyllabusDocumentExtractionRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function replaceForDocument(string $hash,array $extractions):void{$this->entityManager->createQueryBuilder()->delete(SyllabusDocumentExtractionRecord::class,'extraction')->where('extraction.documentSha256=:hash')->setParameter('hash',$hash)->getQuery()->execute();$now=new \DateTimeImmutable('now');foreach($extractions as $extraction){$record=new SyllabusDocumentExtractionRecord();$record->id=$extraction->id;$record->syllabusId=$extraction->syllabusId;$record->documentSha256=$extraction->documentSha256;$record->pageNumber=$extraction->pageNumber;$record->textContent=$extraction->textContent;$record->startOffset=$extraction->startOffset;$record->endOffset=$extraction->endOffset;$record->createdAt=$now;$record->updatedAt=$now;$this->entityManager->persist($record);}} public function listForSyllabus(string $syllabusId):array{return array_map(fn(SyllabusDocumentExtractionRecord $r)=>new SyllabusDocumentExtraction($r->id,$r->syllabusId,$r->documentSha256,$r->pageNumber,$r->textContent,$r->startOffset,$r->endOffset),$this->entityManager->createQueryBuilder()->select('extraction')->from(SyllabusDocumentExtractionRecord::class,'extraction')->where('extraction.syllabusId=:id')->setParameter('id',$syllabusId)->orderBy('extraction.pageNumber','ASC')->getQuery()->getResult());} }
